-- Create separate compute resources for isolation
CREATE WAREHOUSE ingestion_wh WITH WAREHOUSE_SIZE = 'XSMALL';
CREATE WAREHOUSE reporting_wh WITH WAREHOUSE_SIZE = 'MEDIUM';

-- Load data using the ingestion warehouse
COPY INTO raw_inventory FROM @my_stage;

-- Aggregate data using the reporting warehouse
CREATE MATERIALIZED VIEW daily_stock AS SELECT sku, sum(qty) FROM raw_inventory GROUP BY sku;
